WITH lines AS (SELECT id, customer_id, created_at, coupon_codes, pos, item.product_id, item.qty, item.promo FROM carts LATERAL VIEW POSEXPLODE(items) x AS pos, item) SELECT *, PERCENT_RANK() OVER (PARTITION BY customer_id ORDER BY pos DESC) AS pos_percent_rank, NTILE(4) OVER (ORDER BY pos DESC, id, pos) AS pos_bucket, AVG(pos) OVER (ORDER BY created_at, id, pos ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS pos_avg_6_prior, LAG(pos, 1) OVER (ORDER BY created_at, id, pos) AS prev_pos, LEAD(qty, 2) OVER (PARTITION BY promo ORDER BY qty, id, pos) AS next_qty FROM lines
